import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"72. 使用 Valgrind 进行内存检查","description":"The Little Book of C 中文版 — 72. 使用 Valgrind 进行内存检查","frontmatter":{"title":"72. 使用 Valgrind 进行内存检查","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 72. 使用 Valgrind 进行内存检查","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":72,"sidebarWeight":72,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/08-调试测试与 profiling/072-Using Valgrind for Memory Checking.md"};function l(t,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/072-Using Valgrind for Memory Checking)</p><p>如果 gdb 可以帮助您了解程序如何运行，那么 Valgrind 可以帮助您了解程序的泄漏位置。 C 为您提供了对内存的原始控制，这意味着您负责每次分配、释放和指针访问。</p><p>当您需要找到以下内容时，Valgrind 是您最好的朋友：</p><ul><li>内存泄漏（忘记<code>free()</code>)</li><li>无效读/写</li><li>双重免费</li><li>释放后使用错误</li></ul><p>让我们学习如何使用它来使您的程序可靠且无泄漏。</p><h4 id="步骤1-安装valgrind" tabindex="-1">步骤1.安装Valgrind <a class="header-anchor" href="#步骤1-安装valgrind" aria-label="Permalink to &quot;步骤1.安装Valgrind&quot;">​</a></h4><p>在 Linux 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install valgrind</span></span></code></pre></div><p>在 macOS 上（使用 Homebrew）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install valgrind</span></span></code></pre></div><p>使用调试符号编译程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g memory.c -o memory</span></span></code></pre></div><h4 id="步骤-2-使用-valgrind-运行" tabindex="-1">步骤 2. 使用 Valgrind 运行 <a class="header-anchor" href="#步骤-2-使用-valgrind-运行" aria-label="Permalink to &quot;步骤 2. 使用 Valgrind 运行&quot;">​</a></h4><p>在 Valgrind 下运行你的程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind ./memory</span></span></code></pre></div><p>Valgrind 在虚拟 CPU 中运行您的程序并监视每个内存操作。最后，它打印分配和泄漏的详细报告。</p><h4 id="步骤-3-一个简单的例子" tabindex="-1">步骤 3. 一个简单的例子 <a class="header-anchor" href="#步骤-3-一个简单的例子" aria-label="Permalink to &quot;步骤 3. 一个简单的例子&quot;">​</a></h4><p>这是一个有两个常见错误的程序：泄漏和无效释放。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    p[10] = 42;  // invalid write (out of bounds)</span></span>
<span class="line"><span>    return 0;    // forgot to free(p)</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -g mem_bug.c -o mem_bug</span></span>
<span class="line"><span>valgrind ./mem_bug</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid write of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (mem_bug.c:6)</span></span>
<span class="line"><span>==1234==  Address 0x5201048 is 0 bytes after a block of size 40 alloc&#39;d</span></span>
<span class="line"><span>==1234==    at 0x484186F: malloc (vg_replace_malloc.c:380)</span></span>
<span class="line"><span>==1234==</span></span>
<span class="line"><span>==1234== HEAP SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 40 bytes in 1 blocks</span></span>
<span class="line"><span>==1234== LEAK SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 40 bytes in 1 blocks</span></span></code></pre></div><p>Valgrind 捕获了无效访问和泄漏。</p><h4 id="步骤-4-修复错误" tabindex="-1">步骤 4. 修复错误 <a class="header-anchor" href="#步骤-4-修复错误" aria-label="Permalink to &quot;步骤 4. 修复错误&quot;">​</a></h4><p>正确版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(10 * sizeof(int));</span></span>
<span class="line"><span>    if (!p) return 1;</span></span>
<span class="line"><span>    p[9] = 42;   // valid index</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>再次运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind ./mem_bug</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>== All heap blocks were freed -- no leaks are possible</span></span>
<span class="line"><span>== ERROR SUMMARY: 0 errors from 0 contexts</span></span></code></pre></div><p>干净又完美。</p><h4 id="步骤-5-检测释放后使用" tabindex="-1">步骤 5. 检测释放后使用 <a class="header-anchor" href="#步骤-5-检测释放后使用" aria-label="Permalink to &quot;步骤 5. 检测释放后使用&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(sizeof(int));</span></span>
<span class="line"><span>    *p = 5;</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, *p); // using freed memory</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>瓦尔格林德 说：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid read of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (use_after_free.c:7)</span></span>
<span class="line"><span>==1234==  Address 0x5201040 is 0 bytes inside a block of size 4 free&#39;d</span></span></code></pre></div><p>它甚至显示了块被释放的位置。</p><h4 id="步骤-6-检测双重释放" tabindex="-1">步骤 6. 检测双重释放 <a class="header-anchor" href="#步骤-6-检测双重释放" aria-label="Permalink to &quot;步骤 6. 检测双重释放&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *p = malloc(4);</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>    free(p);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Valgrind 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Invalid free() / delete / delete[]</span></span>
<span class="line"><span>==1234==    at 0x4845DEF: free (vg_replace_malloc.c:872)</span></span>
<span class="line"><span>==1234==  Address 0x5201040 was freed previously</span></span></code></pre></div><h4 id="步骤-7-内存泄漏类别" tabindex="-1">步骤 7. 内存泄漏类别 <a class="header-anchor" href="#步骤-7-内存泄漏类别" aria-label="Permalink to &quot;步骤 7. 内存泄漏类别&quot;">​</a></h4><p>Valgrind 将泄漏分为几类：</p><table tabindex="0"><thead><tr><th>类型</th><th>意义</th></tr></thead><tbody><tr><td>肯定输了</td><td>没有指向该块的指针保留，真正的泄漏</td></tr><tr><td>间接损失</td><td>被泄露的块引用</td></tr><tr><td>可能丢失</td><td>指针可能存在但Valgrind无法确认</td></tr><tr><td>仍然可达</td><td>程序结束但内存未释放（通常是无害的）</td></tr></tbody></table><h4 id="步骤-8-获取干净的报告" tabindex="-1">步骤 8. 获取干净的报告 <a class="header-anchor" href="#步骤-8-获取干净的报告" aria-label="Permalink to &quot;步骤 8. 获取干净的报告&quot;">​</a></h4><p>仅检查是否存在真正的泄漏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --leak-check=full --show-leak-kinds=definite ./program</span></span></code></pre></div><p>对于更详细的跟踪：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --track-origins=yes ./program</span></span></code></pre></div><p>该标志告诉您未初始化的变量首次出现的位置。</p><h4 id="步骤-9-检查堆栈或未初始化的值" tabindex="-1">步骤 9. 检查堆栈或未初始化的值 <a class="header-anchor" href="#步骤-9-检查堆栈或未初始化的值" aria-label="Permalink to &quot;步骤 9. 检查堆栈或未初始化的值&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int x;</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x); // uninitialized read</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Valgrind 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== Use of uninitialised value of size 4</span></span>
<span class="line"><span>==1234==    at 0x1091A: main (uninit.c:5)</span></span></code></pre></div><p>始终初始化变量！</p><h4 id="步骤-10-小代码-泄漏检测器" tabindex="-1">步骤 10. 小代码：泄漏检测器 <a class="header-anchor" href="#步骤-10-小代码-泄漏检测器" aria-label="Permalink to &quot;步骤 10. 小代码：泄漏检测器&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>void leak1(void) { malloc(100); }</span></span>
<span class="line"><span>void leak2(void) { char *p = malloc(50); free(p); }</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    leak1();</span></span>
<span class="line"><span>    leak2();</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>跑步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>valgrind --leak-check=full ./leaks</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>==1234== 100 bytes in 1 blocks are definitely lost in loss record 1 of 1</span></span>
<span class="line"><span>==1234== LEAK SUMMARY:</span></span>
<span class="line"><span>==1234==    definitely lost: 100 bytes in 1 blocks</span></span></code></pre></div><p>仅有的<code>leak1()</code>忘记了<code>free()</code>，Valgrind 准确地指出了这一点。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>Valgrind 可以帮助您：</p><ul><li>查找隐藏的内存泄漏</li><li>检测无效指针的使用</li><li>捕获未初始化的值</li><li>编写更安全、更干净、更可靠的C</li></ul><p>它是工作流程中必不可少的工具，特别是对于长时间运行的程序、服务器或系统软件。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>编写一个分配多个块但忘记释放其中一个的程序。</p><p>故意使用<code>p[10]</code>在一个<code>malloc(10)</code>堵塞。</p><p>触发释放后使用并在 Valgrind 中找到它。</p><p>使用<code>--track-origins=yes</code>跟踪未初始化的数据。</p><p>重构您的代码，直到 Valgrind 报告：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>All heap blocks were freed -- no leaks are possible</span></span></code></pre></div><p>接下来，您将探索断言和防御性编程，这些技术可以在逻辑错误达到运行时崩溃之前捕获它们。</p>`,74)])])}const u=s(i,[["render",l]]);export{g as __pageData,u as default};
